def _parse_token(word, chunk="O", pnp="O", relation="O", anchor="O", 
                 format=[WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA]):
    """ Returns a list of token tags parsed from the given <word> element.
        Tags that are not attributes in a <word> (e.g., relation) can be given as parameters.
    """
    if format is None:
        format = [WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA]
    if isinstance(format, str):
        format = [format]
    if not isinstance(format, list):
        raise TypeError("format must be a list or a string.")
    if not all(x in format for x in [WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA]):
        raise ValueError("format must contain all the following tags: WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA")

    token = []
    for tag in format:
        if tag == WORD:
            token.append(word.text)
        elif tag == POS:
            token.append(word.get("pos"))
        elif tag == CHUNK:
            token.append(chunk)
        elif tag == PNP:
            token.append(pnp)
        elif tag == REL:
            token.append(relation)
        elif tag == ANCHOR:
            token.append(anchor)
        elif tag == LEMMA:
            token.append(word.get("lemma"))
        else:
            raise ValueError("format must contain all the following tags: WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA")
    return token

